// A pending ctrl+r is kept, and so is a full read lost in flight (a ctrl+r, or
// the open's first read): the resume repeats it as a full read. It never refuses.
func (m Model) Leave() (tea.Model, tea.Cmd, bool) {
	if m.level == levelAgents {
		m.agentGen++
		m.fullPending = m.fullPending || (m.reading && m.agentsLoading)
		m.reading, m.agentsLoading = false, false
	}
	return m, nil, true
}

// handleResume restarts the open session's chain under a new generation, which
// drops the answers of any earlier chain. It reads from the cursor, silently;
// a ctrl+r left pending by Leave becomes a full read, with its spinner.
func (m Model) handleResume() (tea.Model, tea.Cmd) {
	if m.level != levelAgents || m.agg == nil {
		return m, nil
	}
	m.agentGen++
	m.pollStopped = false
	if m.fullPending {
		m.fullPending = false
		return m, tea.Batch(m.startRead(true), m.spinner.Tick)
	}
	return m, m.startRead(false)
}

// startRead marks a read in flight and returns it; full reads everything again.
func (m *Model) startRead(full bool) tea.Cmd {
	c := m.agg.Cursor()
	if full {
		c = c.Rewound()
		m.agentsLoading, m.fullPending, m.pollStopped = true, false, false
	}
	m.reading = true
	return readDeltaCmd(m.agentGen, c)
}

// handleKey gives the filter the keyboard first; ctrl+r refreshes the level on
// screen, → and enter open a session, ← and esc go back.
func (m Model) handleKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	pollInterval = 2 * time.Second
	quietPeriod  = 5 * time.Minute
	// idleAfter is how long a "running" agent may stay silent before it reads idle.
	idleAfter = 5 * time.Minute
)

// now is the clock the poll chain reads, replaceable in tests.
var now = time.Now

// usageDeltaMsg carries one incremental read. gen is agentGen at the time the
// read started; at is when it finished.
type usageDeltaMsg struct {
	gen   int
	delta agentusage.Delta
	err   error
	at    time.Time
}

// String and GoString keep the delta's paths out of any formatted dump: fmt
// cannot call the Delta's own redacting methods through an unexported field.
func (m usageDeltaMsg) String() string {
	return fmt.Sprintf("usageDeltaMsg{gen: %d, delta: %v, failed: %t}", m.gen, m.delta, m.err != nil)
}

// GoString is String.
func (m usageDeltaMsg) GoString() string { return m.String() }

// usagePollTickMsg says the poll interval of generation gen has elapsed.
type usagePollTickMsg struct{ gen int }

// agentsResumeMsg asks Update to restart a poll chain that stopped.
type agentsResumeMsg struct{}

// readDeltaCmd reads what changed since c. It owns its Cursor copy and touches
// no model (Rule 110); the answer carries gen and the time of the read.
func readDeltaCmd(gen int, c agentusage.Cursor) tea.Cmd {
	return func() tea.Msg {
		delta, err := agentusage.ReadDelta(c)
		return usageDeltaMsg{gen: gen, delta: delta, err: err, at: now()}
	}
}
